function isPass(actual, expected) {
  return Object.is(actual, expected);
}

function countPassing(results) {
  return results.filter((r) => r === true).length;
}

function allPass(results) {
  return results.every((r) => r === true);
}

function anyFailing(results) {
  return results.some((r) => r === false);
}

function failCount(results) {
  return results.filter((r) => r === false).length;
}

function runCase(fn, args, expected) {
  return Object.is(fn(...args), expected);
}

function firstFailure(names, results) {
  const i = results.indexOf(false);
  return i === -1 ? null : names[i];
}

function failingCases(fn, cases) {
  return cases.filter((c) => !Object.is(fn(...c.args), c.expected)).map((c) => c.name);
}

function countFailing(fn, cases) {
  let failures = 0;
  for (const c of cases) {
    if (!Object.is(fn(...c.args), c.expected)) failures += 1;
  }
  return failures;
}

function firstFailing(fn, cases) {
  for (const c of cases) {
    if (!Object.is(fn(...c.args), c.expected)) return c.name;
  }
  return null;
}
